  chooseRelic(e){if(!['dungeon','dungeonBoss'].includes(e.phase))return;e.phase='reward';P.state.mode='extinction-reward';if(P.Combat?.server||typeof document==='undefined')return;P.Core.clear();const options=[['fossil','Corazón fósil','+35 vida máxima y regeneración constante.'],['predator','Colmillo del depredador','Tras cada derrota obtienes 5 s de +25% daño y +18% velocidad.'],['celestial','Fragmento celeste','Un meteorito pequeño golpea enemigos cercanos cada pocos segundos.']];P.UI.show('Reliquia de Extinción','El Triceratops Fósil cayó. Elige una reliquia para el resto de esta partida.',options.map(([id,title,description])=>({title,description,action:()=>this.applyRelic(e,id)})))},
