    if(e.phase==='fragments'||e.phase==='dungeon'){e.spawnIn-=dt;const alive=s.enemies.filter(q=>q.extinctionDino&&q.hp>0&&(e.phase==='dungeon'?q.dungeonDino:!q.dungeonDino)).length,limit=e.phase==='dungeon'?7:3;if(e.spawnIn<=0&&alive<limit){this.spawnDinosaur(e,e.phase==='dungeon');e.spawnIn=e.phase==='dungeon'?.65:1.5}}
    if(e.phase==='portal'){const near=this.players().some(p=>Math.hypot(p.x-e.x,p.y-e.y)<125);if(near)this.offerPortal(e)}
    if(e.phase==='dungeon'||e.phase==='dungeonChoice'||e.phase==='dungeonBoss'){for(const p of this.players()){const dx=p.x-e.x,dy=p.y-e.y;if(Math.abs(dx)>560)p.x=e.x+Math.sign(dx)*560;if(Math.abs(dy)>360)p.y=e.y+Math.sign(dy)*360}}
