  tickFallingMeteors(e,dt){for(const m of e.fallingMeteors||[]){m.left-=dt;if(m.left>0||m.hit)continue;m.hit=true;P.Entities.burst(m.x,m.y,'#ff7c49');for(const p of this.players()){const d=Math.hypot(p.x-m.x,p.y-m.y);if(d<m.r+16&&p.inv<=0){P.PlayerFeedback.hit(p,m.damage,{x:m.x,y:m.y});p.inv=.65}else if(d<m.r*1.9)p.extinctionSlowUntil=Math.max(p.extinctionSlowUntil||0,P.state.elapsed+2.2)}}e.fallingMeteors=(e.fallingMeteors||[]).filter(m=>m.left>-.45)},
